/**
 * Meeting room entity.
 *
 * @trace DSN-001 REQ-001 REQ-005 REQ-012
 */
export class Room {
  constructor(public id: string, public name: string, public capacity: number, public floor: number, public equipment: string[], public active: boolean) {}
}

import { Booking } from '../domain-model/Booking.js';
import { BookingService } from '../domain-services/BookingService.js';
import { AdminGuard } from './AdminGuard.js';

/**
 * HTTP routes for creating, listing, changing and cancelling bookings.
 *
 * @trace DSN-004 REQ-002 REQ-004 REQ-010 REQ-011 REQ-009
 */
export class BookingController {
  constructor(private readonly bookingService: BookingService, private readonly adminGuard: AdminGuard) {}

  async createBooking(roomId: string, start: string, end: string, name: string, email: string): Promise<Booking> {
    const startDate = this.parseDate(start, 'start');
    const endDate = this.parseDate(end, 'end');
    if (!roomId || !name || !email) {
      throw new Error('roomId, name and email are required');
    }
    return this.bookingService.create(roomId, startDate, endDate, name, email);
  }

  async listMyBookings(email: string): Promise<Booking[]> {
    if (!email) {
      throw new Error('email is required');
    }
    return this.bookingService.listByEmail(email);
  }

  async getRoomSchedule(roomId: string, date: string): Promise<Booking[]> {
    if (!roomId || !date) {
      throw new Error('roomId and date are required');
    }
    return this.bookingService.listByRoomAndDay(roomId, date);
  }

  async changeBooking(id: string, email: string, start: string, end: string): Promise<Booking> {
    const startDate = this.parseDate(start, 'start');
    const endDate = this.parseDate(end, 'end');
    if (!email) {
      throw new Error('email is required');
    }
    return this.bookingService.changeTime(id, email, startDate, endDate);
  }

  async cancelBooking(id: string, email: string): Promise<void> {
    if (!email) {
      throw new Error('email is required');
    }
    await this.bookingService.cancelByUser(id, email);
  }

  async adminCancelBooking(token: string, id: string): Promise<void> {
    this.adminGuard.requireAdmin(token);
    await this.bookingService.cancelByAdmin(id);
  }

  private parseDate(value: string, label: string): Date {
    const date = new Date(value);
    if (!value || Number.isNaN(date.getTime())) {
      throw new Error(`Invalid ${label} date: ${value}`);
    }
    return date;
  }
}

import { AdminAuthService } from '../domain-services/AdminAuthService.js';

/**
 * HTTP route for admin login.
 *
 * @trace DSN-005 REQ-009
 */
export class AdminController {
  constructor(private readonly adminAuthService: AdminAuthService) {}

  /**
   * Verifies the admin password and returns an admin token.
   * Throws an Error when the password is missing or wrong.
   */
  async login(password: string): Promise<string> {
    if (typeof password !== 'string' || password.length === 0) {
      throw new Error('Password is required');
    }
    const token = this.adminAuthService.verifyPassword(password);
    if (token === null) {
      throw new Error('Invalid admin password');
    }
    return token;
  }
}

import { Room } from '../domain-model/Room.js';
import { AvailabilityService } from '../domain-services/AvailabilityService.js';
import { RoomService } from '../domain-services/RoomService.js';
import { AdminGuard } from './AdminGuard.js';

/**
 * HTTP routes for rooms, availability and admin room management.
 *
 * @trace DSN-003 REQ-001 REQ-005 REQ-012 REQ-009
 */
export class RoomController {
  constructor(private readonly availabilityService: AvailabilityService, private readonly roomService: RoomService, private readonly adminGuard: AdminGuard) {}

  /**
   * Lists active rooms that are free in the given range.
   */
  async listAvailable(start: string, end: string): Promise<Room[]> {
    const startDate = this.parseDate(start, 'start');
    const endDate = this.parseDate(end, 'end');
    if (endDate.getTime() <= startDate.getTime()) {
      throw new Error('End must be after start');
    }
    const rooms = await this.availabilityService.findFreeRooms(startDate, endDate);
    return rooms.filter((room) => room.active);
  }

  /**
   * Lists all rooms for an admin.
   */
  async listAllRooms(token: string): Promise<Room[]> {
    this.adminGuard.requireAdmin(token);
    return this.roomService.listAll();
  }

  /**
   * Creates a room for an admin.
   */
  async createRoom(token: string, room: Omit<Room, "id">): Promise<Room> {
    this.adminGuard.requireAdmin(token);
    return this.roomService.addRoom(room);
  }

  /**
   * Edits a room for an admin.
   */
  async updateRoom(token: string, id: string, room: Partial<Room>): Promise<Room> {
    this.adminGuard.requireAdmin(token);
    return this.roomService.editRoom(id, room);
  }

  /**
   * Deletes a room for an admin.
   */
  async deleteRoom(token: string, id: string): Promise<void> {
    this.adminGuard.requireAdmin(token);
    await this.roomService.deleteRoom(id);
  }

  /**
   * Activates or deactivates a room for an admin.
   */
  async setRoomActive(token: string, id: string, active: boolean): Promise<Room> {
    this.adminGuard.requireAdmin(token);
    return this.roomService.setActive(id, active);
  }

  private parseDate(value: string, label: string): Date {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      throw new Error(`Invalid ${label} date`);
    }
    return date;
  }
}

import { Room } from './Room.js';

/**
 * Booking of a room for a time range, with creator name and email.
 *
 * @trace DSN-002 REQ-002 REQ-003 REQ-004 REQ-008
 */
export class Booking {
  constructor(public id: string, public roomId: string, public startTime: Date, public endTime: Date, public creatorName: string, public creatorEmail: string, public cancelled: boolean) {
  }

  /** Returns true when this booking belongs to the given room. */
  private belongsTo(room: Room): boolean {
    return this.roomId === room.id;
  }
}

